def sqrt_integer(x: int) -> int:
    if x < 2: return x
    l, r, ans = 1, x // 2, 1
    while l <= r:
        mid = (l + r) // 2
        if mid * mid <= x:
            ans = mid
            l = mid + 1
        else:
            r = mid - 1
    return ans

