def min_stack_ops(operations: list[tuple]) -> list:
    stack = []
    min_stack = []
    output = []
    for op in operations:
        cmd = op[0]
        if cmd == 'push':
            val = op[1]
            stack.append(val)
            if not min_stack or val <= min_stack[-1]:
                min_stack.append(val)
            else:
                min_stack.append(min_stack[-1])
        elif cmd == 'pop':
            if stack:
                stack.pop()
                min_stack.pop()
        elif cmd == 'top':
            output.append(stack[-1] if stack else None)
        elif cmd == 'get_min':
            output.append(min_stack[-1] if min_stack else None)
    return output

